import java.io.*;
import java.util.*;

public class Main {

    static class Point {
        long[] coords;

        public Point(long... coords) {
            this.coords = coords;
        }

        long getLengthSquared() {
            long sum = 0;
            for (long c : coords) {
                sum += c * c;
            }
            return sum;
        }

        long dot(Point other) {
            long total = 0;
            for (int i = 0; i < coords.length; i++) {
                total += this.coords[i] * other.coords[i];
            }
            return total;
        }

        Point subtract(Point other) {
            long[] newCoords = new long[coords.length];
            for (int i = 0; i < coords.length; i++) {
                newCoords[i] = this.coords[i] - other.coords[i];
            }
            return new Point(newCoords);
        }
    }

    public static boolean isValid(List<Point> pts, int index) {
        Point p = pts.get(index);
        int size = pts.size();
        for (int j = 0; j < size; j++) {
            if (j == index) continue;
            for (int k = 0; k < size; k++) {
                if (k == index || k == j) continue;
                Point x = pts.get(j).subtract(p);
                Point y = pts.get(k).subtract(p);
                if (x.dot(y) > 0) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        if (n > 11) {
            System.out.println(0);
            return;
        }
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            long[] coords = new long[5];
            for (int j = 0; j < 5; j++) {
                coords[j] = Long.parseLong(parts[j]);
            }
            points.add(new Point(coords));
        }
        List<Integer> validPoints = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (isValid(points, i)) {
                validPoints.add(i + 1);
            }
        }
        System.out.println(validPoints.size());
        for (int v : validPoints) {
            System.out.println(v);
        }
    }
}
